import React from 'react';
import { FaPlus, FaEye, FaEdit, FaTrash } from 'react-icons/fa';

export function BoutonAjouter({ onClick, texte = "Ajouter", className = "" }) {
  return (
    <button 
      className={`bg-green-500 hover:bg-green-600 text-white py-2 px-4 rounded-md transition duration-300 flex items-center ${className}`}
      onClick={onClick}
    >
      <FaPlus className="mr-2" /> {texte}
    </button>
  );
}

export function BoutonVoir({ onClick, className = "" }) {
  return (
    <button 
      onClick={onClick} 
      className={`text-blue-600 hover:text-blue-900 mr-3 ${className}`}
      title="Voir les détails"
    >
      <FaEye />
    </button>
  );
}

export function BoutonModifier({ onClick, className = "" }) {
  return (
    <button 
      onClick={onClick} 
      className={`text-yellow-600 hover:text-yellow-900 mr-3 ${className}`}
      title="Modifier"
    >
      <FaEdit />
    </button>
  );
}

export function BoutonSupprimer({ onClick, className = "" }) {
  return (
    <button 
      onClick={onClick} 
      className={`text-red-600 hover:text-red-900 ${className}`}
      title="Supprimer"
    >
      <FaTrash />
    </button>
  );
}
